import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  label?: string;
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);

  const updateTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    updateTags(tags.filter((existing) => existing !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>{label}</span>

      <JxTagInput
        ariaLabel={label}
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={updateTags}
      />

      <div
        style={{ display: 'flex', flexWrap: 'wrap', gap: '6px', minHeight: '32px' }}
        role="list"
        aria-label="Выбранные теги"
      >
        {tags.length === 0 ? (
          <JxEmptyState
            title="Тегов пока нет"
            message="Добавьте тег в поле выше — он появится здесь."
          />
        ) : (
          tags.map((tag) => (
            <div key={tag} role="listitem">
              <JxChip removable onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

